### A02: Cryptographic Failures

**Attack:** Lưu password plaintext, dùng weak encryption.

```javascript
// ❌ VULNERABLE
const password = 'mySecret123';
db.save({ password }); // Plaintext!

// Weak encryption
const encrypted = CryptoJS.MD5(password); // Không an toàn

// ✅ SECURE
const bcrypt = require('bcrypt');
const saltRounds = 12;

async function hashPassword(password) {
  return await bcrypt.hash(password, saltRounds);
}

async function verifyPassword(password, hash) {
  return await bcrypt.compare(password, hash);
}

// Dùng AES-256 cho sensitive data
const crypto = require('crypto');
const algorithm = 'aes-256-gcm';

function encrypt(text, secretKey) {
  const iv = crypto.randomBytes(16);
  const cipher = crypto.createCipheriv(algorithm, secretKey, iv);
  let encrypted = cipher.update(text, 'utf8', 'hex');
  encrypted += cipher.final('hex');
  const authTag = cipher.getAuthTag();
  return { iv: iv.toString('hex'), encrypted, authTag: authTag.toString('hex') };
}
```

**Phòng chống:**
- Hash password với bcrypt/argon2
- Dùng TLS 1.3 cho data transit
- Encrypt sensitive data at rest (AES-256)
- Không hardcode keys

