### A03: Injection (SQL, NoSQL, XSS)

#### SQL Injection

```javascript
// ❌ VULNERABLE
const query = `SELECT * FROM users WHERE id = '${userId}'`;
// Attack: userId = "1' OR '1'='1"

// ✅ SECURE - Parameterized query
const query = 'SELECT * FROM users WHERE id = $1';
const result = await db.query(query, [userId]);

// ✅ SECURE - ORM (Sequelize)
const user = await User.findOne({ where: { id: userId } });
```

#### XSS (Cross-Site Scripting)

```javascript
// ❌ VULNERABLE
app.get('/search', (req, res) => {
  res.send(`<h1>Results for: ${req.query.q}</h1>`);
  // Attack: ?q=<script>steal(document.cookie)</script>
});

// ✅ SECURE
const DOMPurify = require('dompurify');
const { JSDOM } = require('jsdom');
const window = new JSDOM('').window;
const purify = DOMPurify(window);

app.get('/search', (req, res) => {
  const clean = purify.sanitize(req.query.q);
  res.send(`<h1>Results for: ${clean}</h1>`);
});

// Content Security Policy
app.use((req, res, next) => {
  res.setHeader('Content-Security-Policy', "default-src 'self'");
  next();
});
```

#### NoSQL Injection

```javascript
// ❌ VULNERABLE
app.post('/login', (req, res) => {
  const user = await User.findOne({
    username: req.body.username,
    password: req.body.password
  });
  // Attack: {"username": "admin", "password": {"$gt": ""}}
});

// ✅ SECURE
app.post('/login', (req, res) => {
  const { username, password } = req.body;

  // Validate types
  if (typeof username !== 'string' || typeof password !== 'string') {
    return res.status(400).json({ error: 'Invalid input' });
  }

  const user = await User.findOne({ username, password });
});
```

