### A04: Insecure Design

```javascript
// ❌ VULNERABLE - No rate limiting
app.post('/api/reset-password', async (req, res) => {
  const { email } = req.body;
  const token = generateToken();
  await sendEmail(email, token);
  res.json({ message: 'Reset link sent' });
});

// ✅ SECURE - Rate limiting + secure design
const rateLimit = require('express-rate-limit');

const resetLimiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 3, // 3 requests
  message: 'Too many reset attempts'
});

app.post('/api/reset-password', resetLimiter, async (req, res) => {
  const { email } = req.body;

  // Always return same message (prevent email enumeration)
  const user = await User.findOne({ email });
  if (user) {
    const token = generateSecureToken();
    await saveResetToken(user.id, token, Date.now() + 3600000);
    await sendEmail(email, token);
  }

  res.json({ message: 'If email exists, reset link sent' });
});
```

