## 2. LLM Integration

### Base Interface

```typescript
// src/services/llm/base.ts
export interface LLMMessage {
  role: 'system' | 'user' | 'assistant';
  content: string;
}

export interface LLMOptions {
  temperature?: number;
  maxTokens?: number;
  topP?: number;
  stop?: string[];
}

export interface LLMResponse {
  content: string;
  usage: {
    promptTokens: number;
    completionTokens: number;
    totalTokens: number;
  };
  model: string;
}

export abstract class BaseLLMAdapter {
  abstract chat(
    messages: LLMMessage[],
    options?: LLMOptions
  ): Promise<LLMResponse>;

  abstract chatStream(
    messages: LLMMessage[],
    options?: LLMOptions
  ): AsyncGenerator<string>;
}
```

### OpenAI Adapter

```typescript
// src/services/llm/openai.ts
import OpenAI from 'openai';
import { BaseLLMAdapter, LLMMessage, LLMOptions, LLMResponse } from './base';

export class OpenAIAdapter extends BaseLLMAdapter {
  private client: OpenAI;
  private model: string;

  constructor(apiKey: string, model: string = 'gpt-4') {
    super();
    this.client = new OpenAI({ apiKey });
    this.model = model;
  }

  async chat(messages: LLMMessage[], options: LLMOptions = {}): Promise<LLMResponse> {
    const response = await this.client.chat.completions.create({
      model: this.model,
      messages,
      temperature: options.temperature ?? 0.7,
      max_tokens: options.maxTokens ?? 2048,
      top_p: options.topP ?? 1,
      stop: options.stop,
    });

    const choice = response.choices[0];

    return {
      content: choice.message.content || '',
      usage: {
        promptTokens: response.usage?.prompt_tokens || 0,
        completionTokens: response.usage?.completion_tokens || 0,
        totalTokens: response.usage?.total_tokens || 0,
      },
      model: response.model,
    };
  }

  async *chatStream(messages: LLMMessage[], options: LLMOptions = {}): AsyncGenerator<string> {
    const stream = await this.client.chat.completions.create({
      model: this.model,
      messages,
      temperature: options.temperature ?? 0.7,
      max_tokens: options.maxTokens ?? 2048,
      stream: true,
    });

    for await (const chunk of stream) {
      const content = chunk.choices[0]?.delta?.content;
      if (content) {
        yield content;
      }
    }
  }
}
```

### Anthropic Adapter

```typescript
// src/services/llm/anthropic.ts
import Anthropic from '@anthropic-ai/sdk';
import { BaseLLMAdapter, LLMMessage, LLMOptions, LLMResponse } from './base';

export class AnthropicAdapter extends BaseLLMAdapter {
  private client: Anthropic;
  private model: string;

  constructor(apiKey: string, model: string = 'claude-3-opus-20240229') {
    super();
    this.client = new Anthropic({ apiKey });
    this.model = model;
  }

  async chat(messages: LLMMessage[], options: LLMOptions = {}): Promise<LLMResponse> {
    // Anthropic requires system message separate
    const systemMessage = messages.find(m => m.role === 'system')?.content || '';
    const chatMessages = messages.filter(m => m.role !== 'system');

    const response = await this.client.messages.create({
      model: this.model,
      max_tokens: options.maxTokens ?? 2048,
      system: systemMessage,
      messages: chatMessages.map(m => ({
        role: m.role as 'user' | 'assistant',
        content: m.content,
      })),
      temperature: options.temperature ?? 0.7,
    });

    const content = response.content[0];

    return {
      content: content.type === 'text' ? content.text : '',
      usage: {
        promptTokens: response.usage.input_tokens,
        completionTokens: response.usage.output_tokens,
        totalTokens: response.usage.input_tokens + response.usage.output_tokens,
      },
      model: response.model,
    };
  }

  async *chatStream(messages: LLMMessage[], options: LLMOptions = {}): AsyncGenerator<string> {
    const systemMessage = messages.find(m => m.role === 'system')?.content || '';
    const chatMessages = messages.filter(m => m.role !== 'system');

    const stream = this.client.messages.stream({
      model: this.model,
      max_tokens: options.maxTokens ?? 2048,
      system: systemMessage,
      messages: chatMessages.map(m => ({
        role: m.role as 'user' | 'assistant',
        content: m.content,
      })),
    });

    for await (const event of stream) {
      if (event.type === 'content_block_delta' && event.delta.type === 'text_delta') {
        yield event.delta.text;
      }
    }
  }
}
```

### LLM Factory

```typescript
// src/services/llm/factory.ts
import { BaseLLMAdapter } from './base';
import { OpenAIAdapter } from './openai';
import { AnthropicAdapter } from './anthropic';

export type LLMProvider = 'openai' | 'anthropic';

export class LLMFactory {
  static create(provider: LLMProvider, config: Record<string, string>): BaseLLMAdapter {
    switch (provider) {
      case 'openai':
        return new OpenAIAdapter(
          config.OPENAI_API_KEY,
          config.OPENAI_MODEL || 'gpt-4'
        );
      case 'anthropic':
        return new AnthropicAdapter(
          config.ANTHROPIC_API_KEY,
          config.ANTHROPIC_MODEL || 'claude-3-opus-20240229'
        );
      default:
        throw new Error(`Unknown LLM provider: ${provider}`);
    }
  }
}
```

