import { BaseMemory, MemoryEntry } from './base';
import { LLMMessage, BaseLLMAdapter } from '../llm/base';

export class SummaryMemory extends BaseMemory {
  private llm: BaseLLMAdapter;
  private summary: string = '';
  private recentMessages: MemoryEntry[];
  private maxRecent: number;

  constructor(llm: BaseLLMAdapter, maxRecent: number = 10) {
    super();
    this.llm = llm;
    this.recentMessages = [];
    this.maxRecent = maxRecent;
  }

  async add(entry: MemoryEntry): Promise<void> {
    this.entries.push(entry);
    this.recentMessages.push(entry);

    // Summarize when recent messages exceed limit
    if (this.recentMessages.length > this.maxRecent) {
      await this.summarize();
    }
  }

  private async summarize(): Promise<void> {
    const messagesToSummarize = this.recentMessages.slice(0, -5); // Keep 5 recent

    const conversationText = messagesToSummarize
      .map(m => `${m.role}: ${m.content}`)
      .join('\n');

    const prompt = [
      {
        role: 'system' as const,
        content: 'Summarize the following conversation concisely, keeping key points and context.'
      },
      {
        role: 'user' as const,
        content: `Previous summary:\n${this.summary}\n\nNew conversation:\n${conversationText}\n\nProvide an updated summary:`
      }
    ];

    const response = await this.llm.chat(prompt, { temperature: 0.3, maxTokens: 500 });
    this.summary = response.content;

    // Keep only recent messages
    this.recentMessages = this.recentMessages.slice(-5);
  }

  getMessages(): LLMMessage[] {
    const messages: LLMMessage[] = [];

    // Add summary as system context
    if (this.summary) {
      messages.push({
        role: 'system',
        content: `Conversation summary:\n${this.summary}`,
      });
    }

    // Add recent messages
    messages.push(
      ...this.recentMessages.map(entry => ({
        role: entry.role,
        content: entry.content,
      }))
    );

    return messages;
  }

  clear(): void {
    this.entries = [];
    this.recentMessages = [];
    this.summary = '';
  }

  getHistory(): MemoryEntry[] {
    return [...this.entries];
  }
}
