### Vector Memory (Semantic Search)

```typescript
// src/services/memory/vector.ts
import { BaseMemory, MemoryEntry } from './base';
import { LLMMessage, BaseLLMAdapter } from '../llm/base';
import { Redis } from 'ioredis';

interface VectorEntry extends MemoryEntry {
  embedding: number[];
}

export class VectorMemory extends BaseMemory {
  private redis: Redis;
  private llm: BaseLLMAdapter;
  private keyPrefix: string;
  private sessionId: string;
  private topK: number;

  constructor(
    redis: Redis,
    llm: BaseLLMAdapter,
    sessionId: string,
    topK: number = 5
  ) {
    super();
    this.redis = redis;
    this.llm = llm;
    this.sessionId = sessionId;
    this.keyPrefix = `memory:${sessionId}`;
    this.topK = topK;
  }

  async add(entry: MemoryEntry): Promise<void> {
    // Generate embedding
    const embedding = await this.getEmbedding(entry.content);

    const vectorEntry: VectorEntry = { ...entry, embedding };

    // Store in Redis
    await this.redis.lpush(
      `${this.keyPrefix}:entries`,
      JSON.stringify(vectorEntry)
    );

    this.entries.push(entry);
  }

  private async getEmbedding(text: string): Promise<number[]> {
    // Using OpenAI embeddings (or any embedding service)
    const response = await fetch('https://api.openai.com/v1/embeddings', {
      method: 'POST',
      headers: {
        'Authorization': `Bearer ${process.env.OPENAI_API_KEY}`,
        'Content-Type': 'application/json',
      },
      body: JSON.stringify({
        model: 'text-embedding-ada-002',
        input: text,
      }),
    });

    const data = await response.json();
    return data.data[0].embedding;
  }

  private cosineSimilarity(a: number[], b: number[]): number {
    const dotProduct = a.reduce((sum, val, i) => sum + val * b[i], 0);
    const magnitudeA = Math.sqrt(a.reduce((sum, val) => sum + val * val, 0));
    const magnitudeB = Math.sqrt(b.reduce((sum, val) => sum + val * val, 0));
    return dotProduct / (magnitudeA * magnitudeB);
  }

  async searchRelevant(query: string): Promise<MemoryEntry[]> {
    const queryEmbedding = await this.getEmbedding(query);

    // Get all entries from Redis
    const entriesJson = await this.redis.lrange(`${this.keyPrefix}:entries`, 0, -1);
    const entries: VectorEntry[] = entriesJson.map(e => JSON.parse(e));

    // Calculate similarity and sort
    const scored = entries
      .map(entry => ({
        entry,
        score: this.cosineSimilarity(queryEmbedding, entry.embedding),
      }))
      .sort((a, b) => b.score - a.score)
      .slice(0, this.topK);

    return scored.map(s => ({
      content: s.entry.content,
      timestamp: new Date(s.entry.timestamp),
      role: s.entry.role,
      metadata: { ...s.entry.metadata, similarity: s.score },
    }));
  }

  async getMessages(query?: string): Promise<LLMMessage[]> {
    if (query) {
      // Use semantic search
      const relevant = await this.searchRelevant(query);
      return relevant.map(entry => ({
        role: entry.role,
        content: entry.content,
      }));
    }

    // Fallback to recent messages
    const entriesJson = await this.redis.lrange(`${this.keyPrefix}:entries`, 0, 9);
    const entries: VectorEntry[] = entriesJson.map(e => JSON.parse(e));

    return entries.reverse().map(entry => ({
      role: entry.role,
      content: entry.content,
    }));
  }

  async clear(): Promise<void> {
    await this.redis.del(`${this.keyPrefix}:entries`);
    this.entries = [];
  }

  getHistory(): MemoryEntry[] {
    return [...this.entries];
  }
}
