## 1. Agent Loop

**Vòng lặp cốt lõi:** Think → Plan → Act → Observe → lặp lại đến khi hoàn thành.

```typescript
// src/core/agent-loop.ts

interface AgentState {
  input: string;
  thoughts: string[];
  actions: Action[];
  observations: string[];
  isComplete: boolean;
  result?: string;
}

interface Action {
  params: Record<string, any>;
}

interface Tool {
  name: string;
  description: string;
  execute: (params: Record<string, any>) => Promise<string>;
}

class AgentLoop {
  private llm: LLMAdapter;
  private tools: Map<string, Tool>;
  private memory: Memory;
  private maxIterations: number;

  constructor(llm: LLMAdapter, memory: Memory, maxIterations: number = 10) {
    this.llm = llm;
    this.tools = new Map();
    this.memory = memory;
    this.maxIterations = maxIterations;
  }

  registerTool(tool: Tool): void {
    this.tools.set(tool.name, tool);
  }

  async run(input: string): Promise<string> {
    const state: AgentState = {
      input,
      thoughts: [],
      actions: [],
      observations: [],
      isComplete: false,
    };

    let iterations = 0;

    while (!state.isComplete && iterations < this.maxIterations) {
      // THINK: Phân tích tình huống
      const thought = await this.think(state);
      state.thoughts.push(thought);

      // PLAN: Quyết định hành động tiếp theo
      const action = await this.plan(state);

      if (action === null) {
        // Agent quyết định đã hoàn thành
        state.isComplete = true;
        state.result = await this.summarize(state);
      } else {
        // ACT: Thực hiện hành động
        state.actions.push(action);
        const observation = await this.act(action);
        state.observations.push(observation);
      }

      iterations++;
    }

    return state.result || 'Đã đạt giới hạn iterations';
  }

  private async think(state: AgentState): Promise<string> {
    const prompt = this.buildThinkPrompt(state);
    const response = await this.llm.chat([
      { role: 'system', content: SYSTEM_PROMPT },
      { role: 'user', content: prompt },
    ]);
    return response.content;
  }

  private async plan(state: AgentState): Promise<Action | null> {
    const toolDescriptions = Array.from(this.tools.values())
      .map(t => `- ${t.name}: ${t.description}`)
      .join('\n');

    const prompt = `
Current state:
- Input: ${state.input}
- Thoughts: ${state.thoughts[state.thoughts.length - 1]}
- Previous actions: ${JSON.stringify(state.actions)}
- Observations: ${state.observations}

Available tools:
${toolDescriptions}

Decide the next action. If the task is complete, respond with "DONE".
Otherwise, respond with JSON: {"tool": "tool_name", "params": {...}}
`;

    const response = await this.llm.chat([
      { role: 'user', content: prompt },
    ]);

    if (response.content.trim() === 'DONE') {
      return null;
    }

    try {
      return JSON.parse(response.content);
    } catch {
      return null;
    }
  }

  private async act(action: Action): Promise<string> {
    const tool = this.tools.get(action.tool);
    if (!tool) {
      return `Error: Tool "${action.tool}" not found`;
    }

    try {
      const result = await tool.execute(action.params);
      return result;
    } catch (error) {
      return `Error executing ${action.tool}: ${error.message}`;
    }
  }

  private async summarize(state: AgentState): Promise<string> {
    const response = await this.llm.chat([
      {
        role: 'system',
        content: 'Summarize the work done based on the thoughts and observations.'
      },
      {
        role: 'user',
        content: `
${state.input}
Thoughts: ${state.thoughts.join('\n')}
Observations: ${state.observations.join('\n')}

Provide a final answer:
`
      }
    ]);
    return response.content;
  }

  private buildThinkPrompt(state: AgentState): string {
    return `
Analyze the current situation and think about what to do next.

Original input: ${state.input}
${state.observations.length > 0 ? `Last observation: ${state.observations[state.observations.length - 1]}` : 'No observations yet.'}

Think step by step:
`;
  }
}

const SYSTEM_PROMPT = `You are an AI agent. Think step by step.
Always explain your reasoning before taking action.`;
```

