// src/memory/short-term.ts

class ShortTermMemory extends BaseMemory {
  private entries: MemoryEntry[] = [];
  private maxEntries: number;

  constructor(maxEntries: number = 50) {
    super();
    this.maxEntries = maxEntries;
  }

  async add(entry: Omit<MemoryEntry, 'id' | 'timestamp'>): Promise<void> {
    const fullEntry: MemoryEntry = {
      ...entry,
      id: crypto.randomUUID(),
      timestamp: new Date(),
    };

    this.entries.push(fullEntry);

    // Keep only recent entries
    if (this.entries.length > this.maxEntries) {
      this.entries = this.entries.slice(-this.maxEntries);
    }
  }

  async search(query: string, topK: number = 5): Promise<MemoryEntry[]> {
    // Simple keyword matching for short-term
    const scored = this.entries
      .map(entry => ({
        entry,
        score: this.calculateRelevance(query, entry.content),
      }))
      .filter(item => item.score > 0)
      .sort((a, b) => b.score - a.score)
      .slice(0, topK);

    return scored.map(item => item.entry);
  }

  async getRecent(count: number): Promise<MemoryEntry[]> {
    return this.entries.slice(-count);
  }

  async clear(): Promise<void> {
    this.entries = [];
  }

  private calculateRelevance(query: string, content: string): number {
    const queryLower = query.toLowerCase();
    const contentLower = content.toLowerCase();

    let score = 0;
    const queryWords = queryLower.split(' ');

    for (const word of queryWords) {
      if (contentLower.includes(word)) {
        score += 1;
      }
    }

    return score / queryWords.length;
  }
}

