// src/memory/manager.ts

class MemoryManager {
  private shortTerm: ShortTermMemory;
  private longTerm: LongTermMemory;
  private working: WorkingMemory;

  constructor(shortTerm: ShortTermMemory, longTerm: LongTermMemory) {
    this.shortTerm = shortTerm;
    this.longTerm = longTerm;
    this.working = new WorkingMemory();
  }

  async addToMemory(
    content: string,
    type: 'user' | 'assistant' | 'system' | 'tool',
    important: boolean = false
  ): Promise<void> {
    const entry = { content, type };

    // Always add to short-term
    await this.shortTerm.add(entry);

    // Add to long-term if important
    if (important) {
      await this.longTerm.add(entry);
    }
  }

  async recall(query: string): Promise<string> {
    // Search both short-term and long-term
    const [shortResults, longResults] = await Promise.all([
      this.shortTerm.search(query, 3),
      this.longTerm.search(query, 3),
    ]);

    // Merge and deduplicate
    const allResults = [...shortResults, ...longResults];
    const unique = this.deduplicate(allResults);

    return unique
      .map(e => `[${e.type}] ${e.content}`)
      .join('\n');
  }

  getWorking(): WorkingMemory {
    return this.working;
  }

  private deduplicate(entries: MemoryEntry[]): MemoryEntry[] {
    const seen = new Set<string>();
    return entries.filter(entry => {
      if (seen.has(entry.content)) return false;
      seen.add(entry.content);
      return true;
    });
  }
}
