// src/planning/planner.ts

class Planner {
  private llm: LLMAdapter;
  private tools: ToolRegistry;

  constructor(llm: LLMAdapter, tools: ToolRegistry) {
    this.llm = llm;
    this.tools = tools;
  }

  async createPlan(goal: string): Promise<Plan> {
    const toolDescriptions = this.tools.getSchemaForLLM();

    const response = await this.llm.chat([
      {
        role: 'system',
        content: `You are a planning agent. Create a step-by-step plan to achieve the goal.
Return a JSON array of steps. Each step should have:
- description: What to do
- tool: Which tool to use (if any)
- params: Parameters for the tool (if applicable)

Available tools:
${toolDescriptions}`
      },
      {
        role: 'user',
        content: `Create a plan for: ${goal}`
      }
    ]);

    const steps: PlanStep[] = JSON.parse(response.content).map(
      (s: any, i: number) => ({
        id: `step-${i}`,
        description: s.description,
        params: s.params,
        status: 'pending',
      })
    );

    return {
      id: crypto.randomUUID(),
      goal,
      steps,
      currentStepIndex: 0,
      status: 'pending',
    };
  }

  async replan(plan: Plan, lastResult: string
